#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int n, m = 0;
vector<int> weight;
vector<vector<int>> tree;

// 返回子树数值和（long long 防止溢出）
long long dfs(int u, int parent) {
    long long s = weight[u];
    for (int v : tree[u]) {
        if (v == parent) continue;
        long long sub = dfs(v, u);
        s += sub;
        if (sub % 2 == 0) {
            m++;
        }
    }
    return s;
}

long long modExp(long long a, long long b) {
    long long res = 1;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    weight.resize(n);
    tree.resize(n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        cin >> weight[i];
        total += weight[i];
    }
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }

    // 总和为奇数时，所有答案均为 0
    if (total % 2 == 1) {
        for (int k = 1; k <= n - 1; k++) {
            cout << 0 << (k == n - 1 ? "\n" : " ");
        }
        return 0;
    }

    dfs(0, -1);

    int maxN = m;
    vector<long long> fact(maxN + 1), invFact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; i++) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invFact[maxN] = modExp(fact[maxN], MOD - 2);
    for (int i = maxN - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % MOD;
    }

    for (int k = 1; k <= n - 1; k++) {
        if (k > m) {
            cout << 0;
        } else {
            long long ans = fact[m] * invFact[k] % MOD * invFact[m - k] % MOD;
            cout << ans;
        }
        if (k != n - 1) cout << " ";
    }
    cout << "\n";
    return 0;
}
